};

export function queryAI(userText) {
  const cleanText = userText.toLowerCase().trim();
  for (const intent of AI_KNOWLEDGE.intents) {
    if (intent.keywords.some(keyword => cleanText.includes(keyword))) {
      return intent.response;
    }
  }
  return AI_KNOWLEDGE.defaultResponse;
}
